function f(t,n){const e=Math.floor(Math.random()*(n-t+1))+t;return new Promise(o=>setTimeout(o,e))}function h(t,n,e){const o=(n-1)*e,r=o+e;return{items:t.slice(o,r),total:t.length,page:n,pageSize:e}}function a(t,n){return Math.random()*(n-t)+t}function m(t){return`${t}-${Date.now()}-${Math.random().toString(36).slice(2,9)}`}function M(t,n,e,o){const r=[],c=Date.now(),u=Math.floor(t*24*60/n),i=n*60*1e3;for(let s=u;s>=0;s--){const l=new Date(c-s*i).toISOString(),d=Math.max(0,e+(Math.random()-.5)*2*o);r.push([l,parseFloat(d.toFixed(2))])}return r}function g(){return[a(10,192)|0,a(0,255)|0,a(0,255)|0,a(1,254)|0].join(".")}function $(t){const n=String(Math.floor(Math.random()*99999)+1).padStart(5,"0");switch(t){case"eNB":return`ENB${n}`;case"gNB":return`GNB${n}`;case"CPE":return`CPE${n}`;case"eGW":return`EGW${n}`;default:return`DEV${n}`}}export{g as a,M as b,m as c,f as d,$ as g,h as p};
